// Transform BAPANAS API response to standardized format
const raw = $input.first().json;

// Handle different response structures
const priceList = raw.data || raw.items || raw || [];
const today = new Date().toISOString().split('T')[0];

const standardized = Array.isArray(priceList) ? priceList.map(item => ({
  commodity_name: item.nama_komoditas || item.commodity || item.name || 'unknown',
  commodity_code: item.kode || item.code || null,
  price: parseFloat(item.harga || item.price || item.nilai || 0),
  unit: item.satuan || item.unit || 'kg',
  province: item.provinsi || item.province || 'Nasional',
  market_name: item.pasar || item.market || 'Rata-rata Nasional',
  price_date: item.tanggal || item.date || today,
  source: 'BAPANAS'
})).filter(p => p.commodity_name !== 'unknown' && p.price > 0)
: [];

return standardized.map(item => ({ json: item }));

// Calculate price changes vs previous day
const items = $input.all();
// Note: In production, query previous prices from PostgreSQL
// For now, attach change calculation placeholder
return items.map(item => ({
  json: {
    ...item.json,
    prev_price: null, // Will be filled by PG query
    change_pct: null  // Calculated after DB upsert
  }
}));

// Handle on-demand market query
const body = $input.first().json.body || $input.first().json;
const commodity = body.commodity || null;
const province = body.province || null;
const days = parseInt(body.days || 30);

return [{
  json: {
    commodity: commodity,
    province: province,
    days: Math.min(days, 365),
    include_prediction: body.include_prediction || true,
    request_id: `mkt_${Date.now()}`
  }
}];

// Linear regression price prediction
const rows = $input.all();
const queryData = $('🔍 Query Parser').item.json;

// Group by commodity
const commodityGroups = {};
for (const row of rows) {
  const name = row.json.commodity_name;
  if (!commodityGroups[name]) commodityGroups[name] = [];
  commodityGroups[name].push({
    date: new Date(row.json.price_date).getTime(),
    price: parseFloat(row.json.price)
  });
}

// Linear regression per commodity
const predictions = {};
for (const [commodity, dataPoints] of Object.entries(commodityGroups)) {
  const sorted = dataPoints.sort((a, b) => a.date - b.date);
  const n = sorted.length;
  if (n < 2) continue;

  const xMean = sorted.reduce((s, d) => s + d.date, 0) / n;
  const yMean = sorted.reduce((s, d) => s + d.price, 0) / n;

  let numerator = 0, denominator = 0;
  for (const d of sorted) {
    numerator += (d.date - xMean) * (d.price - yMean);
    denominator += (d.date - xMean) ** 2;
  }

  const slope = denominator !== 0 ? numerator / denominator : 0;
  const intercept = yMean - slope * xMean;

  // Predict next 7 days
  const futurePrices = [];
  const now = Date.now();
  for (let i = 1; i <= 7; i++) {
    const futureDate = now + i * 86400000;
    futurePrices.push({
      date: new Date(futureDate).toISOString().split('T')[0],
      predicted_price: Math.max(0, Math.round(slope * futureDate + intercept))
    });
  }

  const trend = slope > 0 ? 'naik' : slope < 0 ? 'turun' : 'stabil';
  predictions[commodity] = {
    current_price: sorted[sorted.length - 1].price,
    trend: trend,
    slope_per_day: Math.round(slope * 86400000),
    forecast_7_days: futurePrices,
    data_points: n
  };
}

return [{
  json: {
    success: true,
    query: queryData,
    market_data: commodityGroups,
    predictions: predictions,
    commodities_count: Object.keys(predictions).length,
    metadata: {
      engine: 'agrisensa-market-v2',
      algorithm: 'linear_regression',
      workflow: 'WF-04',
      timestamp: new Date().toISOString()
    }
  }
}];
